// ── State classes ─────────────────────────────────────────────────
class PendingState {
  pay(order) {
    console.log('[Pending] Payment received. Moving to Paid.');
    order.setState(new PaidState());
  }
  ship(order)   { console.log('[Pending] Cannot ship — order not paid yet.'); }
  cancel(order) {
    console.log('[Pending] Order cancelled.');
    order.setState(new CancelledState());
  }
  name() { return 'Pending'; }
}

class PaidState {
  pay(order)  { console.log('[Paid] Already paid.'); }
  ship(order) {
    console.log('[Paid] Order shipped.');
    order.setState(new ShippedState());
  }
  cancel(order) {
    console.log('[Paid] Cancelling and issuing refund.');
    order.setState(new CancelledState());
  }
  name() { return 'Paid'; }
}

class ShippedState {
  pay(order)    { console.log('[Shipped] Already paid.'); }
  ship(order)   { console.log('[Shipped] Already shipped.'); }
  cancel(order) { console.log('[Shipped] Cannot cancel — already shipped.'); }
  name() { return 'Shipped'; }
}

class CancelledState {
  pay(order)    { console.log('[Cancelled] Order is cancelled.'); }
  ship(order)   { console.log('[Cancelled] Order is cancelled.'); }
  cancel(order) { console.log('[Cancelled] Already cancelled.'); }
  name() { return 'Cancelled'; }
}

// ── Context ───────────────────────────────────────────────────────
class Order {
  constructor() { this._state = new PendingState(); }

  setState(state) {
    console.log(`  -> Transition: ${this._state.name()} → ${state.name()}`);
    this._state = state;
  }

  pay()    { this._state.pay(this); }
  ship()   { this._state.ship(this); }
  cancel() { this._state.cancel(this); }
  status() { return this._state.name(); }
}

// ── Usage ─────────────────────────────────────────────────────────
const order = new Order();
console.log('Status:', order.status()); // Pending

order.ship();   // Cannot ship — order not paid yet.
order.pay();    // Payment received → Paid
order.ship();   // Shipped → Shipped
order.cancel(); // Cannot cancel — already shipped.

console.log('Final status:', order.status()); // Shipped

// ── Minimal State skeleton ────────────────────────────────────────
class State {
  handle(ctx) { throw new Error('handle() not implemented'); }
}

class Context {
  constructor(initialState) { this._state = initialState; }
  setState(state) { this._state = state; }
  request()       { this._state.handle(this); }
}

// ── Traffic Light example ─────────────────────────────────────────
class GreenState extends State {
  handle(ctx) {
    console.log('Green — GO');
    ctx.setState(new YellowState());
  }
}
class YellowState extends State {
  handle(ctx) {
    console.log('Yellow — SLOW');
    ctx.setState(new RedState());
  }
}
class RedState extends State {
  handle(ctx) {
    console.log('Red — STOP');
    ctx.setState(new GreenState());
  }
}

const light = new Context(new GreenState());
light.request(); // Green
light.request(); // Yellow
light.request(); // Red
light.request(); // Green (cycles)
